const puppeteer = require('puppeteer-core');

const browser = await puppeteer.launch({
  executablePath: process.env.PUPPETEER_EXECUTABLE_PATH,
  headless: true,
  args: ['--no-sandbox'],
});

const page = await browser.newPage();
await page.goto('https://example.com', { waitUntil: 'networkidle2' });

const title = await page.title();
const screenshot = await page.screenshot({ encoding: 'base64' });

await browser.close();

return {
  json: { title, url: 'https://example.com' },
  binary: {
    data: {
      data: screenshot,
      mimeType: 'image/png',
      fileName: 'screenshot.png',
    },
  },
};

const { chromium } = require('playwright-core');

const browser = await chromium.launch({
  executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH,
  headless: true,
});

const page = await browser.newPage();
await page.goto('https://example.com');
const heading = await page.textContent('h1');
await browser.close();

// Carry the puppeteer step's json/binary forward, add this step's result
return {
  json: { ...$input.item.json, heading },
  binary: $input.item.binary,
};

const Ajv = require('ajv');
const addFormats = require('ajv-formats');

const ajv = new Ajv();
addFormats(ajv);

const schema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    heading: { type: 'string' },
    url: { type: 'string', format: 'uri' },
  },
  required: ['title', 'heading', 'url'],
};

const validate = ajv.compile(schema);
const data = $input.item.json;

if (!validate(data)) {
  throw new Error(`Schema check failed: ${JSON.stringify(validate.errors)}`);
}

return {
  json: { ...data, schemaValid: true },
  binary: $input.item.binary,
};
